'use strict';

/**
 * Sort list and append it below main list
 *
 * @param {Element} targetElement
 * @return void
 */
/* eslint-disable no-shadow */
function sortList(targetElement) {
  const list = [];

  targetElement.querySelectorAll(':scope > li').forEach((el) => {
    list.push({
      salary: el.dataset.salary ? el.dataset.salary : 0,
      element: el,
    });
  });

  const htmlList = list
    .sort(
      (a, b) =>
        Number.parseFloat(b.salary.slice(1)) -
        Number.parseFloat(a.salary.slice(1)),
    )
    .reduce((acc, el) => acc + el.element.outerHTML, '');

  targetElement.innerHTML = htmlList;
}
/* eslint-enable no-shadow */

/**
 * Get array of objects with employees data
 *
 * @param {Element} targetElement
 * @return [Object]
 */
/* eslint-disable no-shadow */
function getEmployees(targetElement) {
  const list = [];

  targetElement.querySelectorAll(':scope > li').forEach((el) => {
    list.push({
      position:
        typeof el.dataset.position === 'string'
          ? el.dataset.position
          : undefined,
      salary: !isNaN(el.dataset.salary) ? Number(el.dataset.salary) : 0,
      age: !isNaN(el.dataset.age) ? Number(el.dataset.age) : 0,
    });
  });

  return list;
}
/* eslint-enable no-shadow */

const targetElement = document.querySelector('ul');

sortList(targetElement);

// eslint-disable-next-line no-unused-vars
const employees = getEmployees(targetElement);
